<script setup lang="ts">
import { t as uiText } from '@/locales'

import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useUserStore} from '@/stores/user'
import * as api from '@/api/modules/moldSales'
import {useCollaborationWorkspace} from '@/stores/collaborationWorkspace'
import {useMoldSalesPreferences,moldSalesProductKey as productKey,type MoldSalesView} from '@/composables/useMoldSalesPreferences'
import MoldSalesMatrix from './MoldSalesMatrix.vue'
import MoldCostEditor from './MoldCostEditor.vue'
import MoldSalesHistoryReview from './MoldSalesHistoryReview.vue'
const props=withDefaults(defineProps<{mode?:'sales'|'production'}>(),{mode:'sales'})
const emit=defineEmits<{maintain:[itemId?:number]}>()
const production=computed(()=>props.mode==='production'),workspace=useCollaborationWorkspace()
const route=useRoute(),router=useRouter(),user=useUserStore()
const data=ref<api.SalesPage>(),matrix=ref<api.MoldSalesMatrixPage>(),keyword=ref(''),filter=ref('all'),brandId=ref<number>(),page=ref(1),size=ref(50),loading=ref(false),recalculating=ref(false),error=ref('')
const preferences=useMoldSalesPreferences(props.mode),presentation=computed(()=>production.value?'detail':preferences.view.value)
const metadata=ref<api.MoldSalesOptions>({products:[],brands:[]}),ready=ref(false),productSearch=ref(''),productsOpen=ref(false)
const options=computed(()=>metadata.value.products),brands=computed(()=>metadata.value.brands)
const defaultKeys=computed(()=>production.value?options.value.map(productKey):(metadata.value.defaultProductKeys??(metadata.value.defaultProductLineIds?options.value.filter(p=>p.productLineId!=null&&metadata.value.defaultProductLineIds!.includes(p.productLineId)).map(productKey):options.value.slice(0,4).map(productKey))))
const selectedKeys=computed(()=>(preferences.savedProductKeys.value??(preferences.savedProductLineIds.value===undefined?defaultKeys.value:options.value.filter(p=>p.productLineId!=null&&preferences.savedProductLineIds.value!.includes(p.productLineId)).map(productKey))).filter(key=>options.value.some(p=>productKey(p)===key)))
const selectedProducts=computed(()=>selectedKeys.value.map(key=>options.value.find(p=>productKey(p)===key)!).filter(Boolean))
const selectedIds=computed(()=>selectedProducts.value.flatMap(p=>p.productLineId==null?[]:[p.productLineId]))
const filteredProducts=computed(()=>options.value.filter(p=>`${p.productName} ${p.productCode||''} ${p.styleCode||''}`.toLowerCase().includes(productSearch.value.trim().toLowerCase())))
const current=computed(()=>presentation.value==='matrix'?matrix.value:data.value)
const choiceOpen=ref(false),choiceRows=ref<{groupId?:number;sourceGroupKey?:string;applicationId?:number;itemId?:number;productName:string;modelNames:string[];phoneCodes:string[];salesQuantity?:number|null}[]>([])
function chooseProducts(keys:string[]){preferences.chooseProductKeys(keys,options.value.filter(p=>keys.includes(productKey(p))).flatMap(p=>p.productLineId==null?[]:[p.productLineId]))}
function toggleProduct(key:string,checked:boolean){chooseProducts(checked?[...selectedKeys.value,key]:selectedKeys.value.filter(value=>value!==key))}
function chooseView(value:MoldSalesView){preferences.chooseView(value)}
function brandNames(row:api.MoldSalesGroup){return row.brandNames?.join(' / ')||'未登记品牌'}
const detailTarget=ref<number|string>(),job=ref<api.SyncJob>(),detail=ref<api.SalesDetail>(),detailOpen=ref(false),detailPage=ref(1),detailTab=ref('orders'),detailLoading=ref(false),detailError=ref('')
const historyOpen=ref(false),history=ref<Awaited<ReturnType<typeof api.getMoldSalesHistory>>>([]),unmatchedOpen=ref(false),historyClassification=ref<api.HistoryClassification|'all'>('all')
const costOpen=ref(false),costGroupId=ref<number>(),costWritable=ref(false)
const archiveOpen=ref(false),archiveSources=ref<api.SalesArchiveSource[]>([]),archiveHash=ref(''),archiveLoading=ref(false),archiveSaving=ref(false),archiveError=ref(''),archiveUnknown=ref(false)
const archiveSource=computed(()=>archiveSources.value.find(source=>source.sha256===archiveHash.value))
let epoch=0,detailEpoch=0,optionsEpoch=0,archiveEpoch=0,readyAuth='',readyOwner:number|undefined,timer:ReturnType<typeof setTimeout>|undefined,poll:ReturnType<typeof setTimeout>|undefined,disposed=false
const status=computed(()=>current.value?.status),isRunning=computed(()=>job.value?.status==='running')
const qty=(n:number|null|undefined)=>n==null?'—':new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(n)
const money=(n:number|null|undefined)=>n==null?'—':new Intl.NumberFormat('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4}).format(n)
const date=(s:string|null|undefined)=>{
 if(!s)return '尚未更新'
 if(/^\d{4}-\d{2}-\d{2}$/.test(s))return s
 const value=new Date(/^\d+$/.test(s)?Number(s):s)
 return Number.isNaN(value.getTime())?'日期待核对':value.toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})
}
const canMaintainCost=computed(()=>status.value?.canReadCost===true&&status.value.canWriteCost===true)
const costLabel=(cost:api.MoldCost,row?:api.MoldSalesGroup)=>cost.source==='actual'?'实际成本':row?.sourceOnly?'单套参考':'预算参考'
const sourceBreakdown=(sources:api.SalesSourceBreakdown|undefined)=>sources?`eccount ${qty(sources.eccount)} · crm ${qty(sources.crm)}`:''
const sourceLabel=(order:api.SalesOrder)=>order.source==='eccount'?'数据来自 eccount':'数据来自 crm'
function orderQuantity(order:api.SalesOrder){return order.quantity==null?'数量未填写':`${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:20}).format(order.quantity)}${order.unit?.trim()?' '+order.unit:' · 单位未填写'}`}
function breakEvenIssue(cost:api.MoldCost){
 if(cost.basis?.unknownFields?.some(field=>['referenceSellingPrice','referenceUnitProductionCost'].includes(field)))return '待补参考售价和单件生产成本，暂不计算回本销量'
 if(cost.breakEvenUnits!=null)return ''
 const price=cost.basis?.referenceSellingPrice?.trim(),unitCost=cost.basis?.referenceUnitProductionCost?.trim()
 if(!price||!unitCost||!Number.isFinite(Number(price))||!Number.isFinite(Number(unitCost)))return '待补参考售价和单件生产成本，暂不计算回本销量'
 return Number(price)<=Number(unitCost)?'参考售价未覆盖单件生产成本，暂不计算回本销量':'回本依据待核对'
}
function componentDifference(row:api.MoldSalesGroup){const p=row.production;if(!p)return '';return [['PC',p.pcTotal],['TPU',p.tpuTotal]].filter(([,value])=>value!==p.finishedTotal).map(([label,value])=>`${label} ${qty(value as number|null)}`).join(' · ')}
const canMaintainRowCost=(row:api.MoldSalesGroup)=>canMaintainCost.value&&!row.readonly&&row.groupId!=null&&row.canWriteCost===true&&!row.costConflict
function editCost(row:api.MoldSalesGroup){if(!status.value?.canReadCost||row.readonly||row.groupId==null)return;costWritable.value=canMaintainRowCost(row);costGroupId.value=row.groupId;costOpen.value=true}
async function costSaved(){await load();if(detailOpen.value&&detail.value)await loadDetail()}
const eligibility:Record<string,string>={eligible:'计入销量',not_finished_stage:'半成品／非最终工序，不计入',not_finished_code:'商品编码待核对',cancelled:'已取消，不计入',deleted:'来源已删除，不计入',quantity_review:'数量待核对',missing_quantity:'数量未填写',identity_conflict:'商品身份待核对',unit_review:'单位待核对',company_review:'公司归属待核对',source_conflict:'来源资料待核对',status_review:'正式订单状态待核对',cancellation_review:'备注有取消疑义，待核对',header_record:'订单主表，明细另计',crm_period_reference:'同期 Excel 仅用于核对 CRM',missing_master:'缺少订单主表',outside_period:'不在本次来源日期范围'}
const orderStates:Record<string,string>={closed:'已完成',deal:'生产中',fully_shipped:'全部发货',partial_shipped:'部分发货',cancelled:'已取消',pending:'待审核',confirmed:'已确认',confirmed_deposit_push_production:'定金确认，已下推生产',sales_confirmed_pending_finance:'销售已确认，待财务',production_completed_pending_final_payment:'生产完成，待尾款',pending_shipment:'待发货',partial_arrived:'部分到货',fully_arrived:'全部到货'}
async function load(){
 if(!ready.value||readyAuth!==user.token||readyOwner!==user.profile?.userId)return
 const ticket=++epoch,auth=user.token;loading.value=true;error.value=''
 const params={page:page.value,size:size.value,keyword:keyword.value.trim(),filter:filter.value,brandId:brandId.value,sort:preferences.sort.value,...(options.value.some(p=>p.productKey)?{productKeys:selectedKeys.value.join(',')}:{productLineIds:selectedIds.value.join(',')}),itemId:Number(route.query.itemId)||undefined,...(production.value?{view:'production'}:{})}
 try{const r=presentation.value==='matrix'?await api.getMoldSalesMatrix(params):await api.getMoldSales(params);if(ticket!==epoch||auth!==user.token)return;if(presentation.value==='matrix')matrix.value=r as api.MoldSalesMatrixPage;else data.value=r as api.SalesPage;job.value=r.status.job;if(job.value?.status==='running')schedulePoll()}catch(e){if(ticket===epoch&&auth===user.token)error.value=e instanceof Error?e.message:'读取失败，请重试'}finally{if(ticket===epoch)loading.value=false}
}
async function refresh(){const ticket=++optionsEpoch,auth=user.token;ready.value=false;loading.value=true;try{const value=await api.getMoldSalesOptions();if(ticket!==optionsEpoch||auth!==user.token)return;metadata.value=value;if(preferences.savedProductKeys.value===undefined&&preferences.savedProductLineIds.value===undefined)chooseProducts(defaultKeys.value);if(brandId.value&&!value.brands.some(b=>b.brandId===Number(brandId.value)))brandId.value=undefined;readyAuth=auth;readyOwner=user.profile?.userId;ready.value=true;await load()}catch(e){if(ticket===optionsEpoch&&auth===user.token){error.value=e instanceof Error?e.message:'产品与品牌读取失败，请重试';loading.value=false}}}
async function refreshStatistics(){
 if(recalculating.value||isRunning.value)return
 const auth=user.token;recalculating.value=true;error.value=''
 try{if(status.value?.canRecalculate)await api.recalculateMoldSales();if(auth===user.token)await refresh()}
 catch(e){if(auth===user.token)error.value=e instanceof Error?e.message:'刷新统计失败，请重试'}
 finally{if(auth===user.token)recalculating.value=false}
}
function reset(){page.value=1;void load()}
watch(keyword,()=>{clearTimeout(timer);timer=setTimeout(reset,300)})
watch(()=>workspace.revision,()=>{void refresh();if(detailOpen.value&&detail.value)void loadDetail()});
watch([filter,brandId,size,presentation,()=>preferences.sort.value,()=>selectedKeys.value.join(',')],reset,{flush:'sync'});watch(()=>route.query.itemId,reset)
function openGroup(target:number|string,tab='orders'){detailTarget.value=target;detail.value=undefined;detailOpen.value=true;detailPage.value=1;detailTab.value=tab;return loadDetail(target)}
function matrixChoices(cell:api.MoldSalesMatrixCell,row:api.MoldSalesMatrixRow){
 const productName=options.value.find(p=>productKey(p)===productKey(cell))?.productName||'产品'
 const keys=cell.sourceGroupKeys?.length?cell.sourceGroupKeys:cell.groupIds.map(id=>`item:${id}`)
 return keys.map(key=>{const group=cell.groups?.find(g=>g.sourceGroupKey===key||g.groupId!=null&&key===`item:${g.groupId}`);const groupId=group?.groupId??(cell.sourceGroupKeys?.length?undefined:cell.groupIds.find(id=>key===`item:${id}`));return {sourceGroupKey:key,groupId:groupId??undefined,productName,modelNames:group?.modelNames||row.modelNames,phoneCodes:group?.phoneCodes||row.phoneCodes,salesQuantity:group?.salesQuantity}})
}
function openMatrix(cell:api.MoldSalesMatrixCell,row:api.MoldSalesMatrixRow){
 const groups=matrixChoices(cell,row)
 if(groups.length===1&&!cell.applicationIds.length){chooseEvidence(groups[0]!);return}
 if(!groups.length&&cell.applicationIds.length===1){void router.push({path:'/mold-applications',query:{applicationId:String(cell.applicationIds[0])}});return}
 if(!groups.length&&!cell.applicationIds.length&&cell.itemIds?.length){
  if(cell.itemIds.length===1){moldItem(cell.itemIds[0]!);return}
  choiceRows.value=cell.itemIds.map(itemId=>({itemId,productName:options.value.find(p=>productKey(p)===productKey(cell))?.productName||'产品',modelNames:row.modelNames,phoneCodes:row.phoneCodes}));choiceOpen.value=true;return
 }
 const productName=options.value.find(p=>productKey(p)===productKey(cell))?.productName||'产品'
 choiceRows.value=[...groups,...cell.applicationIds.map(applicationId=>({applicationId,productName,modelNames:row.modelNames,phoneCodes:row.phoneCodes}))];choiceOpen.value=true
}
function openMatrixTotal(row:api.MoldSalesMatrixRow){const cells=row.cells.filter(c=>c.groupIds.length||c.sourceGroupKeys?.length);if(cells.length===1){openMatrix(cells[0]!,row);return}choiceRows.value=cells.flatMap(cell=>matrixChoices(cell,row));choiceOpen.value=true}
function chooseEvidence(value:typeof choiceRows.value[number]){choiceOpen.value=false;if(value.groupId!=null)void openGroup(value.groupId);else if(value.sourceGroupKey)void openGroup(value.sourceGroupKey);else if(value.applicationId)void router.push({path:'/mold-applications',query:{applicationId:String(value.applicationId)}});else if(value.itemId)moldItem(value.itemId)}
async function pollJob(){const auth=user.token;try{const r=await api.getMoldSalesJob();if(disposed||auth!==user.token)return;job.value=r;if(r.status==='running')schedulePoll();else if(r.status==='completed'){workspace.changed();ElMessage.success(r.kind==='archive'?uiText('历史订单已导入'):r.kind==='historyReview'?uiText('历史分类和型号对照已保存'):uiText('CRM 订单已更新'))}else if(r.status==='failed')error.value=r.message||'更新失败，原数据保留'}catch(e){if(auth===user.token)error.value=e instanceof Error?e.message:'读取更新进度失败，请刷新'}}
function schedulePoll(){clearTimeout(poll);poll=setTimeout(()=>void pollJob(),2500)}
async function sync(){const auth=user.token;try{await ElMessageBox.confirm(uiText('只读更新 CRM 销售订单，取消订单将从有效销量中排除。原有生产数量和模具资料保留。'),uiText('更新 CRM 订单'),{confirmButtonText:uiText('开始更新'),cancelButtonText:uiText('取消')});if(auth!==user.token)return;job.value=await api.syncMoldSales();schedulePoll()}catch(e){if(auth===user.token&&e!=='cancel'&&e!=='close')error.value=e instanceof Error?e.message:'更新未开始'}}
async function open(row:api.MoldSalesGroup,tab='orders'){const target=row.groupId??row.sourceGroupKey;if(target!=null)await openGroup(target,tab)}
async function loadDetail(id=detailTarget.value){
 if(id==null||!detailOpen.value)return
 const ticket=++detailEpoch,auth=user.token;detailLoading.value=true;detailError.value=''
 try{const next=await (typeof id==='string'?api.getMoldSalesSourceDetail(id,detailPage.value,props.mode):production.value?api.getMoldSalesDetail(id,detailPage.value,'production'):api.getMoldSalesDetail(id,detailPage.value));if(ticket===detailEpoch&&auth===user.token)detail.value=next}
 catch(e){if(ticket===detailEpoch&&auth===user.token){const code=(e as {code?:string})?.code;detailError.value=code==='ECONNABORTED'||code==='ETIMEDOUT'||e instanceof Error&&/^timeout of \d+ms exceeded$/i.test(e.message)?'明细读取超时，请重试':'明细读取失败，请重试'}}
 finally{if(ticket===detailEpoch)detailLoading.value=false}
}
watch(detailOpen,opened=>{if(!opened){++detailEpoch;detail.value=undefined;detailTarget.value=undefined;detailLoading.value=false;detailError.value=''}},{flush:'sync'})
async function openHistory(){const auth=user.token;try{const next=await api.getMoldSalesHistory();if(auth===user.token){history.value=next;historyOpen.value=true}}catch(e){error.value=e instanceof Error?e.message:'读取历史失败'}}
function openUnmatched(classification:api.HistoryClassification|'all'='all'){historyClassification.value=classification;unmatchedOpen.value=true}
async function loadArchiveSources(){
 const ticket=++archiveEpoch,auth=user.token;archiveLoading.value=true;archiveError.value=''
 try{const sources=await api.getSalesArchiveSources();if(disposed||ticket!==archiveEpoch||auth!==user.token||!archiveOpen.value)return;archiveSources.value=sources;if(!sources.some(source=>source.sha256===archiveHash.value))archiveHash.value=(sources.find(source=>source.prepared&&!source.imported)||sources[0])?.sha256||''}
 catch(e){if(ticket===archiveEpoch&&auth===user.token)archiveError.value=e instanceof Error?e.message:'历史资料读取失败，请重试'}
 finally{if(ticket===archiveEpoch)archiveLoading.value=false}
}
function openArchiveImport(){if(isRunning.value)return;archiveOpen.value=true;archiveUnknown.value=false;archiveSources.value=[];archiveHash.value='';void loadArchiveSources()}
async function checkArchiveState(){
 const auth=user.token;await Promise.all([loadArchiveSources(),refresh()]);if(disposed||auth!==user.token)return
 if(archiveSource.value?.imported||job.value?.status==='running'||job.value?.status==='failed')archiveUnknown.value=false
}
async function importArchive(){
 const source=archiveSource.value;if(!source||!source.prepared||source.imported||archiveLoading.value||archiveSaving.value||archiveUnknown.value||isRunning.value)return
 const auth=user.token,ticket=++archiveEpoch;archiveSaving.value=true;archiveError.value=''
 try{const result=await api.importSalesArchive({file:source.file,sha256:source.sha256});if(disposed||ticket!==archiveEpoch||auth!==user.token)return;job.value=result;archiveOpen.value=false;if(result.status==='running')schedulePoll();else if(result.status==='completed'){workspace.changed();ElMessage.success(uiText('历史订单已导入'))}else if(result.status==='failed')error.value=result.message||'历史订单未导入，原资料保留'}
 catch(e){if(ticket===archiveEpoch&&auth===user.token){archiveUnknown.value=true;archiveError.value=`${e instanceof Error?e.message:'导入请求未确认'}。请刷新状态核对，暂不重复提交。`}}
 finally{if(ticket===archiveEpoch)archiveSaving.value=false}
}
function maintain(id?:number){detailOpen.value=false;emit('maintain',id)}
function moldItem(itemId:number){void router.push({path:'/molds',query:{itemId}})}
function mold(row:api.MoldSalesGroup){if(!row.readonly&&row.groupId!=null)moldItem(row.groupId)}
watch(()=>user.token,()=>{++epoch;++detailEpoch;++optionsEpoch;++archiveEpoch;clearTimeout(poll);clearTimeout(timer);ready.value=false;data.value=undefined;matrix.value=undefined;metadata.value={products:[],brands:[]};detail.value=undefined;detailTarget.value=undefined;detailOpen.value=false;history.value=[];historyOpen.value=false;unmatchedOpen.value=false;choiceRows.value=[];choiceOpen.value=false;productsOpen.value=false;brandId.value=undefined;job.value=undefined;recalculating.value=false;error.value='';loading.value=false;detailLoading.value=false;costOpen.value=false;costGroupId.value=undefined;archiveOpen.value=false;archiveSources.value=[];archiveHash.value='';archiveError.value='';archiveUnknown.value=false;archiveLoading.value=false;archiveSaving.value=false})
watch(()=>user.profile?.userId,(next,previous)=>{if(next&&next!==previous&&user.token)void refresh()})
onMounted(()=>void refresh())
defineExpose({refresh})
onBeforeUnmount(()=>{disposed=true;++epoch;++detailEpoch;++optionsEpoch;++archiveEpoch;clearTimeout(timer);clearTimeout(poll)})
</script>
<template>
 <section class="mold-sales">
  <header class="sales-titlebar"><h2>{{production?uiText('累计产量'):uiText('模具销量与成本')}}</h2><div v-if="!production" class="view-switch" role="tablist" :aria-label='uiText("销量展示视图")'><button :class="{selected:presentation==='detail'}" role="tab" :aria-selected="presentation==='detail'" @click="chooseView('detail')">{{ uiText("产品明细") }}</button><button :class="{selected:presentation==='matrix'}" role="tab" :aria-selected="presentation==='matrix'" @click="chooseView('matrix')">{{ uiText("型号总览") }}</button></div><div class="tools"><slot name="tools"/><span class="source-date">{{ uiText("CRM 更新：") }}{{date(status?.capturedAt)}}</span><el-button size="small" :loading="recalculating" :disabled="isRunning" @click="refreshStatistics">{{ uiText("刷新统计") }}</el-button><el-button v-if="!production&&(status?.canImportArchive??status?.canSync)" size="small" :disabled="isRunning" @click="openArchiveImport">{{ uiText("导入历史订单") }}</el-button><el-button v-if="status?.canSync" size="small" type="primary" :loading="isRunning" @click="sync">{{ uiText("更新 CRM 订单") }}</el-button><el-button v-if="!production&&status?.canSync&&status.canReadCost" size="small" text @click="openHistory">{{ uiText("取数与成本历史") }}</el-button><el-popover placement="bottom-end" :width="340" trigger="click"><template #reference><el-button size="small" text :aria-label='uiText("销量及资料说明")'>{{ uiText("资料说明") }}</el-button></template><p class="notice">{{ uiText("销量及订单累计依据不代表模具实物或手机适配已经确认。") }}</p><p class="notice">{{ uiText("历史型号、适配等资料缺项不在每个单元格重复显示。点击数量或模具资料可查看原始依据，也可按“型号关联待核对”单独筛选。") }}</p><p v-if="current?.ignoredQuantity" class="notice">{{ uiText("另有 ") }}{{qty(current.ignoredQuantity)}}{{ uiText(" 件历史订单在下单系统未找到对应款式／机型，本次暂不处理，原订单保留。") }}</p></el-popover></div></header>
  <div class="filters">
   <el-input v-model="keyword" :aria-label="production?uiText('搜索累计产量'):uiText('搜索模具销量')" size="small" clearable :placeholder='uiText("搜索品牌、产品、手机型号或编码")'/>
   <el-select :model-value="preferences.sort.value" :aria-label='uiText("排序方式")' size="small" @update:model-value="preferences.chooseSort"><el-option value="phoneCodeDesc" :label='uiText("型号编码：新到旧")'/><el-option value="openedDateDesc" :label='uiText("开模日期：新到旧")'/><el-option value="quantityDesc" :label="production?uiText('累计产量：多到少'):uiText('累计订单：多到少')"/></el-select>
   <el-select v-model="brandId" :aria-label='uiText("品牌筛选")' size="small" clearable :placeholder='uiText("全部品牌")'><el-option v-for="b in brands" :key="b.brandId" :value="b.brandId" :label="b.brandName"/></el-select>
   <el-popover v-model:visible="productsOpen" placement="bottom-start" :width="330" trigger="click" @show="refresh"><template #reference><el-button class="product-picker" size="small">{{presentation==='matrix'?uiText('产品列'):uiText('产品筛选')}}{{ uiText(" · 已选 ") }}{{selectedKeys.length}} <span aria-hidden="true">⌄</span></el-button></template><div class="product-choices"><strong>{{ uiText("产品与历史分类") }}</strong><el-input v-model="productSearch" size="small" clearable :placeholder='uiText("搜索产品名称或编码")' :aria-label='uiText("搜索产品列")'/><div class="choice-tools"><el-button size="small" link type="primary" @click="chooseProducts(defaultKeys)">{{ uiText("常用") }}</el-button><el-button size="small" link type="primary" @click="chooseProducts(options.map(productKey))">{{ uiText("全选") }}</el-button><el-button size="small" link @click="chooseProducts([])">{{ uiText("清空") }}</el-button></div><div class="product-options"><label v-for="p in filteredProducts" :key="productKey(p)"><input type="checkbox" :checked="selectedKeys.includes(productKey(p))" @change="toggleProduct(productKey(p),($event.target as HTMLInputElement).checked)"/><span>{{p.productName}}<small v-if="p.productCode||p.styleCode">{{p.productCode||p.styleCode}}</small></span><small v-if="p.historical" class="draft-label">{{ uiText("历史分类") }}</small><small v-else-if="p.status==='draft'||p.masterDataStatus==='draft'" class="draft-label">{{ uiText("草稿") }}</small></label><p v-if="!filteredProducts.length" class="notice">{{ uiText("暂无符合条件的产品或分类") }}</p></div><p class="notice">{{ uiText("新增产品会进入此清单，已保存的选择保持不变。") }}</p><p v-if="!preferences.storageAvailable.value" class="notice">{{ uiText("浏览器未能保存偏好，本次选择仍有效。") }}</p></div></el-popover>
   <el-select v-model="filter" :aria-label="production?uiText('产量筛选'):uiText('销量筛选')" size="small"><el-option value="all" :label='uiText("全部模具组")'/><template v-if="production"><el-option value="withProduction" :label='uiText("有产量依据")'/><el-option value="missingProduction" :label='uiText("待核对产量")'/></template><template v-else><el-option value="withSales" :label='uiText("有销量")'/><el-option value="missingCost" :label='uiText("成本待补")'/></template><el-option value="unmapped" :label='uiText("型号关联待核对")'/></el-select>
   <span class="totals">{{ uiText("当前筛选 ") }}{{qty(current?.totalElements)}} {{presentation==='matrix'?uiText('款型号'):uiText('组')}} · {{production?uiText('有效订单'):uiText('已选产品销量')}} {{qty(production?current?.totalOrderQuantity:current?.totalSalesQuantity)}}{{ uiText(" 件") }}</span>
  </div>
  <p class="source-scope">{{ uiText("2025年前：数据来自 eccount；2025年起：数据来自 crm。三家公司按订单量合计。") }}<span v-if="status?.archive&&!status.archive.imported">{{ uiText("历史订单尚未导入。") }}</span></p>
  <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button text @click="refresh">{{ uiText("重试") }}</el-button></el-alert>
