  <div v-if="status?.canReadHistoryReview" class="reconciliation-notices"><p class="notice"><el-button link type="primary" @click="openUnmatched()">{{ uiText("历史资料") }}</el-button><el-button v-if="status.historyReview?.applied" link type="primary" @click="openUnmatched('pending')">{{ uiText("当前待补 ") }}{{qty(Number(status.historyReview.summary?.categories.pending.quantity||0))}}{{ uiText(" 件") }}</el-button><span v-else-if="current?.unassignedQuantity"> · {{qty(current.unassignedQuantity)}}{{ uiText(" 件待核对，原单原码保留") }}</span></p></div>
