  <div v-else class="sales-list" role="table" :aria-label="production?uiText('模具累计产量列表'):uiText('模具销量与成本列表')" v-loading="loading">
   <div class="sales-row column-head" :class="{'without-cost':production||!status?.canReadCost}" role="row"><span>{{ uiText("品牌") }}</span><span>{{ uiText("产品") }}</span><span>{{ uiText("手机型号 / 编码") }}</span><span>{{ uiText("开模日期") }}</span><span>{{production?uiText('累计产量'):uiText('有效订单件数')}}</span><template v-if="!production&&status?.canReadCost"><span>{{ uiText("模具成本") }}</span><span>{{ uiText("每件分摊") }}</span><span>{{ uiText("参考回本销量") }}</span></template><span>{{ uiText("操作") }}</span></div>
   <div class="sales-body">
    <article v-for="r in data?.content" :key="r.sourceGroupKey||r.groupId!" class="sales-row" :class="{'without-cost':production||!status?.canReadCost}" role="row">
