     <div class="product-identity" role="cell"><small class="narrow-label">{{ uiText("产品") }}</small><strong>{{r.productName||r.styleName}}</strong></div>
     <div class="identity" role="cell"><small class="narrow-label">{{ uiText("手机型号") }}</small><button @click="open(r)"><span>{{r.modelNames.join(' / ')||uiText('未登记型号')}}</span></button><small v-if="r.phoneCodes.length">{{ uiText("编码 ") }}{{r.phoneCodes.join(' / ')}}</small><small v-if="r.coverageLabel&&!['historical','needs_review'].includes(r.coverageState||'')" class="coverage-label">{{uiText(String((r.coverageLabel) ?? ''))}}</small></div>
     <div role="cell" class="opening-date"><small class="narrow-label">{{ uiText("开模日期") }}</small><span :title="r.openedDateSource==='first_order'?uiText('按首笔有效订单日期补充'):undefined">{{r.openedDate||'—'}}</span></div>
     <div role="cell" class="metric"><small class="narrow-label">{{production?uiText('累计产量'):uiText('有效订单')}}</small><button class="quantity-link" @click="open(r)">{{qty(production?r.production?.finishedTotal:r.salesQuantity)}}<small>{{ uiText("件") }}</small></button><small v-if="r.sourceBreakdown" class="source-breakdown">{{sourceBreakdown(r.sourceBreakdown)}}</small><small v-if="production&&componentDifference(r)" class="component-difference">{{ uiText("部件差异：") }}{{componentDifference(r)}}</small></div>
     <template v-if="!production&&status?.canReadCost"><div role="cell" class="metric"><small class="narrow-label">{{ uiText("模具成本") }}</small><strong v-if="r.costConflict">{{ uiText("成本归属待核对") }}</strong><template v-else><strong>{{r.cost?'¥'+money(r.cost.totalCost):r.sourceOnly?'—':uiText('成本待补')}}</strong><small v-if="r.cost">{{costLabel(r.cost,r)}}<template v-if="r.cost.source!=='actual'&&!r.sourceOnly"> · {{r.cost.costSets}}{{ uiText(" 套") }}</template></small></template></div><div role="cell" class="metric"><small class="narrow-label">{{ uiText("每件分摊") }}</small><strong>{{!r.costConflict&&r.cost?.perUnitCost!=null?'¥'+money(r.cost.perUnitCost):'—'}}</strong><small v-if="r.salesQuantity===0">{{ uiText("暂无有效销量") }}</small></div><div role="cell" class="metric"><small class="narrow-label">{{ uiText("参考回本销量") }}</small><span>{{!r.costConflict&&r.cost?.breakEvenUnits!=null?qty(r.cost.breakEvenUnits)+uiText(' 件'):'—'}}</span><small v-if="!r.costConflict&&r.cost?.remainingUnits!=null">{{r.cost.remainingUnits>0?uiText('还差 ')+qty(r.cost.remainingUnits)+uiText(' 件'):uiText('已达到参考销量')}}</small></div></template>
     <div role="cell" class="row-tools"><el-button size="small" link type="primary" @click="open(r)">{{production?uiText('产量依据'):uiText('查看明细')}}</el-button><el-button v-if="production&&!r.readonly&&r.groupId!=null" size="small" link @click="maintain(r.groupId)">{{ uiText("补录／更正") }}</el-button><template v-else><el-button v-if="canMaintainRowCost(r)" size="small" link type="primary" @click="editCost(r)">{{ uiText("维护成本") }}</el-button><el-button v-if="!r.readonly&&r.groupId!=null" size="small" link @click="mold(r)">{{ uiText("模具资料") }}</el-button></template></div>
    </article>
    <el-empty v-if="data&&!data.content.length" :description="status?.connected?uiText('当前条件下暂无模具'):uiText('尚未拉取 CRM 订单，点击上方更新后查看')"/>
   </div>
  </div>
  <footer><small>{{status?.periodStart||'2025-01-01'}}{{ uiText(" 至 ") }}{{status?.periodEnd||uiText('今天')}}，{{production?uiText('列表显示成品累计，部件差异另示。以已计入的订单件数为累计依据，交付与否不影响计入；与已有人工累计分别取较大值，共模归并、不重复相加。'):uiText('按已计入的手机壳订单量分摊；待核对原行另存，不当作确定销量。实际成本优先，否则仅作预算参考；共模机型合并，整套成本不重复计算。')}}</small><el-pagination v-model:current-page="page" v-model:page-size="size" :total="current?.totalElements||0" :pager-count="5" size="small" layout="prev,pager,next" @current-change="load"/></footer>
  <el-drawer v-model="choiceOpen" :title='uiText("选择查看依据")' size="min(620px,96vw)"><p class="notice">{{ uiText("同一型号下有多份档案，分别查看原订单及成本。") }}</p><button v-for="value in choiceRows" :key="value.sourceGroupKey||(value.groupId?`g${value.groupId}`:value.applicationId?`a${value.applicationId}`:`m${value.itemId}`)" class="evidence-choice" @click="chooseEvidence(value)"><strong>{{value.productName}}</strong><span>{{value.modelNames.join(' / ')}}</span><small>{{ uiText("编码 ") }}{{value.phoneCodes.join(' / ')||uiText('待核对')}} · {{value.groupId?uiText('档案 ')+value.groupId:value.sourceGroupKey?uiText('历史订单'):value.applicationId?uiText('申请 ')+value.applicationId:uiText('模具档案 ')+value.itemId}}<template v-if="value.salesQuantity!=null"> · {{qty(value.salesQuantity)}}{{ uiText(" 件") }}</template></small></button></el-drawer>
  <el-drawer v-model="detailOpen" class="sales-detail" :title="production?uiText('累计产量与订单依据'):uiText('模具销量与成本明细')" size="min(1080px,96vw)" :destroy-on-close="true">
   <div v-loading="detailLoading" :element-loading-text="uiText('加载中')" class="detail-content"><el-alert v-if="detailError" :title="uiText(detailError)" type="error" :closable="false"><el-button text @click="loadDetail()">{{ uiText("重试") }}</el-button></el-alert><template v-else-if="detail">
    <p class="opening-date detail-opening-date">{{ uiText("开模日期") }}：{{detail.group.openedDate||'—'}}<small v-if="detail.group.openedDateSource==='first_order'">{{ uiText("按首笔有效订单日期补充") }}</small></p><h3>{{detail.group.productName||detail.group.styleName}} · {{detail.group.modelNames.join(' / ')}}</h3>
    <div class="detail-summary"><span v-if="production">{{ uiText("有效订单 ") }}{{qty(detail.group.production?.orderQuantity)}}{{ uiText(" 件 · PC ") }}{{qty(detail.group.production?.pcTotal)}} · TPU {{qty(detail.group.production?.tpuTotal)}}{{ uiText(" · 成品 ") }}{{qty(detail.group.production?.finishedTotal)}}</span><span v-else>{{ uiText("有效销量 ") }}{{qty(detail.group.salesQuantity)}}{{ uiText(" 件") }}</span><span v-if="!production&&status?.canReadCost&&detail.group.cost&&!detail.group.costConflict">{{costLabel(detail.group.cost,detail.group)}} ¥{{money(detail.group.cost.totalCost)}}{{ uiText(" · 每件分摊 ¥") }}{{money(detail.group.cost.perUnitCost)}}</span><el-button v-if="!production&&canMaintainRowCost(detail.group)" size="small" @click="editCost(detail.group)">{{ uiText("维护成本") }}</el-button><el-button v-if="!detail.group.readonly&&detail.group.groupId!=null" size="small" @click="mold(detail.group)">{{ uiText("核对模具与共模机型") }}</el-button></div>
