    <p class="notice">{{ uiText("手机型号编码：") }}{{detail.group.phoneCodes.join(' / ')||uiText('待核对')}}</p>
    <p v-if="detail.group.coverageLabel||detail.group.unmapped" class="notice coverage-evidence"><span v-if="detail.group.coverageLabel">{{uiText(String((detail.group.coverageLabel) ?? ''))}}</span><span v-if="detail.group.unmapped">{{detail.group.sourceOnly?uiText(' · 原型号保留，适配关系待核对。'):uiText(' · 型号关联资料未齐，请在模具资料中补充真实适用手机。')}}</span></p>
    <p v-for="a in detail.group.salesAliases" :key="a.phoneCode" class="notice alias-evidence">{{ uiText("历史编码 ") }}{{a.phoneCode}}{{ uiText(" 已关联本档案：") }}{{a.reason}}{{ uiText("。订单原名称及编码保留。") }}</p>
    <el-tabs v-model="detailTab"><el-tab-pane :label="production?uiText('订单依据'):uiText('订单明细')" name="orders"/><el-tab-pane v-if="production||status?.canReadCost" :label="production?uiText('产量依据'):uiText('成本依据')" name="cost"/></el-tabs>
    <template v-if="detailTab==='orders'">
     <p class="notice">{{production?uiText('已登记且可核实的订单计入，不以发货、到货或完成状态为门槛。同一共模组的机型和颜色合计一次；取消、删除和待核对明细不计入。'):uiText('每行保留原订单。2025年前取 eccount，2025年起取 crm；同期 Excel 仅核对，不重复叠加。多个颜色合计到同一模具组；多个实物套的销量不做无依据拆分。')}}</p>
     <div class="phone-breakdown"><span v-for="p in detail.phoneSales" :key="p.phoneCode">{{p.modelName}}（{{p.targetPhoneCode||p.phoneCode}}）：{{qty(p.quantity)}}{{ uiText(" 件") }}<small v-if="p.historicalAlias">{{ uiText("原编码 ") }}{{p.phoneCode}}{{ uiText(" · 原名 ") }}{{p.originalModelName||uiText('未填写')}}<template v-if="p.associationReason"> · {{p.associationReason}}</template></small></span></div>
     <div class="order-list"><article v-for="o in detail.orders" :key="o.sourceId" class="order-row"><div><strong>{{o.orderNo||uiText('原单未填外部单号')}}</strong><small>{{o.businessDate||o.date||(o.orderDate?date(o.orderDate):uiText('原订单未填日期'))}}</small><small>{{orderStates[o.orderStatus]||o.orderStatus||uiText('原单未填状态')}}</small><small class="order-source">{{uiText(String((sourceLabel(o)) ?? ''))}}<template v-if="o.company"> · {{o.company}}</template></small></div><div>{{o.name}}<small v-if="o.originalProductName">{{ uiText("原商品：") }}{{o.originalProductName}}</small><small>{{o.specification}}</small><small>{{o.itemCode}}</small><small v-if="o.sourceFile" class="order-location">{{ uiText("原件：") }}{{o.sourceFile}}<template v-if="o.sourceSheet"> · {{o.sourceSheet}}</template><template v-if="o.sourceRow!=null">{{ uiText(" · 第 ") }}{{o.sourceRow}}{{ uiText(" 行") }}</template></small></div><div><strong>{{orderQuantity(o)}}</strong><small :class="{'excluded':o.eligibility!=='eligible'}">{{production&&o.eligibility==='eligible'?uiText('计入累计依据'):eligibility[o.eligibility]||uiText('原单待核对')}}</small></div></article></div>
     <el-pagination v-model:current-page="detailPage" :page-size="20" :total="detail.totalElements" :pager-count="5" size="small" layout="total,prev,pager,next" @current-change="loadDetail()"/>
    </template>
    <template v-else-if="detailTab==='cost'">
     <template v-if="production">
      <p class="notice">{{ uiText("按 ") }}{{status?.periodStart}}{{ uiText(" 至 ") }}{{status?.periodEnd}}{{ uiText(" 的已计入订单件数作为累计依据，不按交付进度筛选。人工原值保留，每一项累计分别取已有记录与订单数量的较大值；同一共模组多条旧档案的累计也取较大值。") }}</p>
      <p v-if="detail.group.delivery" class="notice">{{ uiText("未交付订单 ") }}{{qty(detail.group.delivery.pendingQuantity)}}{{ uiText(" 件；部分交付订单涉及 ") }}{{qty(detail.group.delivery.partialOrderQuantity)}}{{ uiText(" 件。两项均已包含在订单累计依据内；部分交付不推算未交件数。") }}</p>
      <dl class="production-breakdown"><dt>{{ uiText("项目") }}</dt><dt>{{ uiText("已有人工累计") }}</dt><dt>{{ uiText("销售订单依据") }}</dt><dt>{{ uiText("本页累计") }}</dt><template v-for="[key,manual,label] in [['pcTotal','manualPcTotal','PC 半成品'],['tpuTotal','manualTpuTotal','TPU 半成品'],['finishedTotal','manualFinishedTotal','成品']] as const" :key="key"><dt>{{label}}</dt><dd>{{qty(detail.group.production?.[manual])}}</dd><dd>{{qty(detail.group.production?.orderQuantity)}}</dd><dd>{{qty(detail.group.production?.[key])}}</dd></template></dl>
      <p class="notice">{{ uiText("原始补录记录与更正历史") }}</p><article v-for="record in detail.group.productionRecords" :key="record.itemId" class="history-record"><strong>{{record.modelName}}{{ uiText(" · 档案 ") }}{{record.itemId}}</strong><p>PC {{qty(record.pcTotal)}} · TPU {{qty(record.tpuTotal)}}{{ uiText(" · 成品 ") }}{{qty(record.finishedTotal)}}</p><p v-if="record.productionNotes">{{record.productionNotes}}</p><el-button size="small" @click="maintain(record.itemId)">{{ uiText("补录／更正本档案") }}</el-button></article>
      <p class="notice">{{ uiText("CRM 更新：") }}{{date(status?.capturedAt)}}{{ uiText("。原订单和历次取数依据保留；上面的累计结果根据当前依据计算，不覆盖人工填写值。") }}</p>
     </template>
     <template v-else-if="status?.canReadCost">
      <el-alert v-if="detail.group.costConflict" :title='uiText("成本归属待核对，请先核对模具与共模机型，历史成本不自动合并。")' type="warning" :closable="false"/>
      <template v-else-if="detail.group.cost">
       <dl v-if="detail.group.cost.source==='actual'&&detail.group.cost.actual" class="cost-breakdown actual-cost-breakdown"><dt>{{ uiText("制模费") }}</dt><dd>¥{{money(detail.group.cost.actual.manufacturingCost)}}</dd><dt>{{ uiText("运费") }}</dt><dd>¥{{money(detail.group.cost.actual.freightCost)}}</dd><dt>{{ uiText("清关费") }}</dt><dd>¥{{money(detail.group.cost.actual.customsCost)}}</dd><dt>{{ uiText("其他费用") }}</dt><dd>¥{{money(detail.group.cost.actual.otherCost)}}</dd><dt>{{ uiText("本组实际成本") }}</dt><dd>¥{{money(detail.group.cost.totalCost)}}</dd><dt>{{ uiText("最近维护") }}</dt><dd>{{detail.group.cost.actual.updatedBy}} · {{date(detail.group.cost.actual.updatedAt)}}</dd></dl>
       <p v-else class="notice">{{detail.group.sourceOnly?uiText("单套参考成本；实物套数待核，未计为实际总成本。"):uiText("尚未维护实际成本，当前金额仅为预算参考。")}}</p>
       <p class="cost-apportionment">{{detail.group.sourceOnly?uiText("单套参考分摊：¥"):uiText("本组分摊：¥")}}{{money(detail.group.cost.totalCost)}} ÷ {{qty(detail.group.salesQuantity)}}{{ uiText(" 件 = ") }}{{detail.group.cost.perUnitCost==null?uiText('暂无销量，暂不计算'):'¥'+money(detail.group.cost.perUnitCost)+uiText('/件')}}</p>
       <section class="break-even-evidence"><h4>{{ uiText("参考回本销量") }}</h4><template v-if="detail.group.cost.breakEvenUnits!=null"><p class="break-even-result"><strong>{{qty(detail.group.cost.breakEvenUnits)}}{{ uiText(" 件") }}</strong><span v-if="detail.group.cost.remainingUnits!=null">{{detail.group.cost.remainingUnits>0?uiText('还差 ')+qty(detail.group.cost.remainingUnits)+uiText(' 件'):uiText('已达到参考销量')}}</span></p><p v-if="detail.group.cost.basis" class="notice">{{ uiText("本组") }}{{detail.group.cost.source==='actual'?uiText('实际成本'):uiText('预算')}} ¥{{money(detail.group.cost.totalCost)}}{{ uiText(" ÷（参考售价 ¥") }}{{detail.group.cost.basis.referenceSellingPrice}}{{ uiText(" − 单件生产成本 ¥") }}{{detail.group.cost.basis.referenceUnitProductionCost}}{{ uiText("），向上取整。") }}</p><p class="notice">{{ uiText("按订单量估算，不代表已收到货款或收回实际投入。") }}</p></template><p v-else class="notice">{{breakEvenIssue(detail.group.cost)}}</p></section>
       <el-button v-if="!detail.group.readonly&&detail.group.groupId!=null" size="small" @click="editCost(detail.group)">{{ uiText("查看成本记录") }}</el-button>
